export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  cursed?: boolean;
  enchantment?: number;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS_THRESHOLD = 2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// The single place that knows how the item catalogue is stored; pricing
// policies ask it for a type's listed base premium rather than indexing.
function listedBasePremium(type: string): number {
  return BASE_PREMIUMS[type];
}

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

// "Alike" means the same item type: 2 runes + 1 moonstone form no block,
// while 3 runes + 3 moonstones form two separate blocks.
function groupAlikeItems(items: Item[]): Map<string, number> {
  const countsPerAlikeGroup = new Map<string, number>();
  for (const item of items) {
    countsPerAlikeGroup.set(item.type, (countsPerAlikeGroup.get(item.type) ?? 0) + 1);
  }
  return countsPerAlikeGroup;
}

function qualifiesForComponentBlock(count: number): boolean {
  return count === COMPONENT_BLOCK_SIZE;
}

function basePremiumForAlikeGroup(type: string, count: number): number {
  if (qualifiesForComponentBlock(count)) {
    return COMPONENT_BLOCK_BASE_PREMIUM;
  }
  return count * listedBasePremium(type);
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
}

// Item-specific modifiers apply to the base premium of the affected item,
// not to the policy total.
function itemSurcharges(item: Item): number {
  const itemBasePremium = listedBasePremium(item.type);
  let surcharges = 0;
  if (item.cursed === true) {
    surcharges += itemBasePremium * CURSE_SURCHARGE_RATE;
  }
  if (isHighlyEnchanted(item)) {
    surcharges += itemBasePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE;
  }
  return surcharges;
}

// The spec's "policy base premium": the sum of all item base premiums,
// before any item-specific or policy-wide modifier.
function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of groupAlikeItems(items)) {
    total += basePremiumForAlikeGroup(type, count);
  }
  return total;
}

function totalItemSurcharges(items: Item[]): number {
  return items.reduce((total, item) => total + itemSurcharges(item), 0);
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
}

// Policy-wide modifiers are percentages of the policy base premium itself,
// not of the premium already raised by item-specific surcharges.
function policyModifiers(
  customer: Customer,
  basePremium: number,
  previousContracts: number,
): number {
  let modifiers = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  if (isLongStandingCustomer(customer)) {
    modifiers -= basePremium * LOYALTY_DISCOUNT_RATE;
  }
  if (previousContracts > 0) {
    modifiers -= basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE;
  }
  return modifiers;
}

function roundPremiumInMHPCOsFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
  const basePremium = policyBasePremium(items);
  const premium =
    basePremium +
    totalItemSurcharges(items) +
    policyModifiers(customer, basePremium, previousContracts) +
    PROCESSING_FEE;
  return roundPremiumInMHPCOsFavour(premium);
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  const results: QuoteResult[] = [];
  for (const step of scenario.steps) {
    results.push({ premium: quote(scenario.customer, step.items, results.length) });
  }
  return { results };
}

import { describe, expect, it } from "vitest";
import { quote, runScenario } from "./claim-office.js";

describe("MHPCO claim office", () => {
  // --- Quote: base premiums per item type ---
  it("quotes an empty item list as 5 G (processing fee only)", () => {
    expect(quote({ yearsWithMHPCO: 5 }, [])).toBe(5);
  });
  it("quotes a single plain sword -- base premium 100 G, +10 % first insurance, +5 G fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
  });
  it("quotes a single plain amulet -- base premium 60 G, +10 % first insurance, +5 G fee = 71 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
  });
  it("quotes a single plain staff -- base premium 80 G, +10 % first insurance, +5 G fee = 93 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
  });
  it("quotes a single plain potion -- base premium 40 G, +10 % first insurance, +5 G fee = 49 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
  });
  it("quotes 2 runes -- component base premium 25 G each = 50 G, +10 % first insurance, +5 G fee = 60 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("quotes 2 moonstones -- component base premium 25 G each = 50 G, +10 % first insurance, +5 G fee = 60 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }, { type: "moonstone" }])).toBe(60);
  });

  // --- Insurance values per item type (observable via claim cap) ---
  it.todo("insures a sword at 1000 G -- policy cap 2000 G");
  it.todo("insures an amulet at 600 G -- policy cap 1200 G");
  it.todo("insures a staff at 800 G -- policy cap 1600 G");
  it.todo("insures a potion at 400 G -- policy cap 800 G");
  it.todo("insures a rune at 250 G -- policy cap 500 G");
  it.todo("insures a moonstone at 250 G -- policy cap 500 G");

  // --- Component building blocks ---
  it("quotes 2 runes -- 50 G base premium, no block (block requires exactly 3)", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
  });
  it("quotes 3 runes -- 60 G base premium (block of 3 alike components applies), +10 % +5 G fee = 71 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
  });
  it("quotes 4 runes -- 100 G base premium (no block -- block requires exactly 3), +10 % +5 G fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, Array(4).fill({ type: "rune" }))).toBe(115);
  });
  it("quotes 7 runes -- 175 G base premium (no block), +10 % +5 G fee = 197.5 G rounded up to 198 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, Array(7).fill({ type: "rune" }))).toBe(198);
  });
  it("quotes 2 runes + 1 moonstone -- 75 G base premium, no block ('alike' means the same type), +10 % +5 G fee = 87.5 rounded up to 88 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(88);
  });
  it("quotes 3 runes + 3 moonstones -- 120 G base premium (two separate blocks), +10 % +5 G fee = 137 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [...Array(3).fill({ type: "rune" }), ...Array(3).fill({ type: "moonstone" })])).toBe(137);
  });
  it.todo("quotes a sword + 3 runes with insurance sum 1750 G -- block discount affects premium only, cap 3500 G");

  // --- Item-specific premium modifiers ---
  it("adds a 50 % curse surcharge to a cursed sword -- base 100 G becomes 150 G; policy-wide modifiers apply to the 100 G policy base premium: +10 G first insurance +5 G fee = 165 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }])).toBe(165);
  });
  it("adds a 30 % high-enchantment surcharge for enchantment exactly 5 -- sword base 100 G becomes 130 G; +10 G first insurance (10 % of the 100 G policy base premium) +5 G fee = 145 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }])).toBe(145);
  });
  it("adds no high-enchantment surcharge for enchantment 4 -- sword base premium stays 100 G, +10 % +5 G fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }])).toBe(115);
  });
  it("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 100 + 50 + 30 = 180 G; +10 G first insurance +5 G fee = 195 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5, cursed: true }])).toBe(195);
  });
  it("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 160 G base + 50 G curse = 210 G; +16 G first insurance (10 % of the 160 G policy base premium) +5 G fee = 231 G", () => {
    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }, { type: "amulet" }])).toBe(231);
  });

  // --- Policy-wide premium modifiers ---
  it("applies a 20 % loyalty discount for a customer with exactly 2 years with MHPCO -- sword 100 G - 20 G loyalty + 10 G first insurance + 5 G fee = 95 G", () => {
    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }])).toBe(95);
  });
  it("applies no loyalty discount for a customer with 1 year with MHPCO -- sword 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }])).toBe(115);
  });
  it.todo("applies a 10 % first-insurance surcharge to the policy base premium");
  it("applies a 15 % follow-up discount to every quote after the customer's first quote -- second sword quote 100 G + 10 G first insurance - 15 G follow-up + 5 G fee = 100 G", () => {
    const { results } = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "sword" }] },
        { op: "quote", items: [{ type: "sword" }] },
      ],
    });
    expect(results).toEqual([{ premium: 115 }, { premium: 100 }]);
  });
  it("applies no follow-up discount to the customer's first quote -- sword 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    const { results } = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(results).toEqual([{ premium: 115 }]);
  });
  it.todo("adds the 5 G processing fee at the very end of every premium");
  it.todo("still applies the first-insurance surcharge on a follow-up contract -- each quoted item is treated as a first insurance");

  // --- Rounding (premium) ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Quote integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, first contract) as 165 G");
  it.todo("quotes a long-standing customer's second contract for a cursed steel sword (enchantment 7, 3 years) as 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("pays out 400 G for a regular steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
  it.todo("pays out 100 G for a damaged rune (insurance value 250 G) with 200 G damage -- no enchantment or material, no special clause");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G damage -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 %: dragon sword, damage 1000 G -> payout 400 G");
  it.todo("reimburses a steel sword with enchantment 9 and damage 1000 G at 50 % then deductible -> payout 400 G");
  it.todo("reimburses a dragon-material sword with enchantment 5 and damage 800 G fully then deductible -> payout 700 G");
  it.todo("applies the 50 % rule ahead of full dragon reimbursement: dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies no special clause to a dragon-material item below enchantment 8 other than full reimbursement -- see dragon enchantment 5 case");

  // --- Claim: cap ---
  it.todo("reports remainingCap 600 G after a first 1500 G claim on a sword policy (cap 2000 G, payout 1400 G)");
  it.todo("reduces a second 1500 G claim to the remaining cap 600 G -> payout 600 G, remainingCap 0 G");
  it.todo("caps a policy of sword + amulet at 3200 G (insurance sum 1600 G)");
  it.todo("bases the cap on unmodified insurance values: cursed sword premium 165 G, cap still 2000 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats two {itemType: 'sword'} damage entries on a two-sword policy as separate damages with their own deductibles");
  it.todo("rejects a claim with more damage entries of a type than the policy covers -- CLI exits non-zero, error on stderr");

  // --- Rounding (payout) ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
  it.todo("keeps intermediate payout amounts as fractions and rounds only the final payout");

  // --- Error cases (observable contract: CLI exits non-zero, writes to stderr, no results on stdout) ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- CLI exits non-zero, error on stderr, no results on stdout");
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only sword insured) -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim damage entry with an unknown item type -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim damage entry with a negative amount (-200) -- CLI exits non-zero, error on stderr");

  // --- CLI contract ---
  it.todo("reads a scenario JSON from stdin and writes {results: [...]} to stdout in step order");
  it.todo("writes a quote result as {premium: integer} and a claim result as {payout, remainingCap} integers");
  it.todo("resolves a claim step's policy field as the zero-based index of the quote step that created the policy");
});
